"use client"
import React, {useState} from 'react'
import {useRouter} from 'next/navigation'

export default function RegisterPage(){
  const [name,setName] = useState('')
  const [email,setEmail] = useState('')
  const [password,setPassword] = useState('')
  const router = useRouter()

  async function onSubmit(e:React.FormEvent){
    e.preventDefault()
    try{
      const res = await fetch('http://localhost:3000/api/auth/register',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,email,password})})
      if(!res.ok) throw new Error('Failed')
      router.push('/dashboard')
    }catch(err){
      alert('Registration failed')
    }
  }

  return (
    <div style={{maxWidth:560,margin:'40px auto',padding:24,background:'#fff',borderRadius:10}}>
      <h2>Create account</h2>
      <form onSubmit={onSubmit} style={{display:'grid',gap:12}}>
        <input placeholder="Full name" value={name} onChange={e=>setName(e.target.value)} />
        <input placeholder="Email" value={email} onChange={e=>setEmail(e.target.value)} />
        <input placeholder="Password" type="password" value={password} onChange={e=>setPassword(e.target.value)} />
        <button style={{padding:'8px 12px',background:'#059669',color:'#fff',border:'none',borderRadius:6}}>Create account</button>
      </form>
      <p style={{marginTop:12}}>Already have an account? <a href="/login">Sign in</a></p>
    </div>
  )
}
"use client"
import React, { useState } from 'react'
import { register } from '../../../lib/api'

export default function RegisterPage() {
  const [form, setForm] = useState({ name: '', email: '', phone: '' })
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function submit(e: React.FormEvent) {
    e.preventDefault()
    setLoading(true)
    setError(null)
    try {
      await register(form)
      window.location.href = '/dashboard'
    } catch (err: any) { setError(err?.message || 'Register failed') }
    finally { setLoading(false) }
  }

  return (
    <div className="max-w-md mx-auto mt-12">
      <h1 className="text-2xl font-semibold mb-4">Register</h1>
      <form onSubmit={submit} className="space-y-3">
        <input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Full name" className="w-full p-3 border rounded" />
        <input value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="Email" className="w-full p-3 border rounded" />
        <input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})} placeholder="Phone" className="w-full p-3 border rounded" />
        <button disabled={loading} className="w-full bg-green-600 text-white p-3 rounded">{loading ? 'Creating...' : 'Create account'}</button>
        {error && <div className="text-red-600">{error}</div>}
      </form>
    </div>
  )
}
